namespace qqworld_collector\module\collecting\method; use qqworld_collector\lib; class jsonpath extends lib { var $guid = 'jsonpath'; var $loaded = false; public function __construct() { add_filter( 'qqworld-collector-collecting-method-' . $this->guid, array($this, 'parse'), 10, 3); } public function includes() { if (!$this->loaded) { $jsonpath = __DIR__ . DIRECTORY_SEPARATOR . '..' . DIRECTORY_SEPARATOR . 'classes' . DIRECTORY_SEPARATOR . 'JSONPath' . DIRECTORY_SEPARATOR; require $jsonpath . 'Filters' . DIRECTORY_SEPARATOR . 'AbstractFilter.php'; require $jsonpath . 'Filters' . DIRECTORY_SEPARATOR . 'IndexesFilter.php'; require $jsonpath . 'Filters' . DIRECTORY_SEPARATOR . 'IndexFilter.php'; require $jsonpath . 'Filters' . DIRECTORY_SEPARATOR . 'QueryMatchFilter.php'; require $jsonpath . 'Filters' . DIRECTORY_SEPARATOR . 'QueryResultFilter.php'; require $jsonpath . 'Filters' . DIRECTORY_SEPARATOR . 'RecursiveFilter.php'; require $jsonpath . 'Filters' . DIRECTORY_SEPARATOR . 'SliceFilter.php'; require $jsonpath . 'AccessHelper.php'; require $jsonpath . 'JSONPathException.php'; require $jsonpath . 'JSONPathLexer.php'; require $jsonpath . 'JSONPathToken.php'; require $jsonpath . 'JSONPath.php'; $this->loaded = true; } } public function parse($html, $value, $index) { $this->includes(); $html = trim($html); $html = json_decode($html, true); if ($html) { $this->results = array(); $value = explode("\r\n", $value); foreach ($value as $val) { $val = html_entity_decode($val); $parser = new \Flow\JSONPath\JSONPath($html); $parser = $parser->find($val); $results = $parser->data(); if (count($results)) { if ($index == -1) { $results = array($results[count($results)-1]); } elseif ($index != 'all') { if (isset($results[$index])) $results = array($results[$index]); else $results = array($results[count($results)-1]); } foreach ($results as $result) { if (is_array($result)) $result = json_encode($result, JSON_INVALID_UTF8_IGNORE); $this->results[] = $result; } } } } else { $this->results = ''; } return $this->results; } } ?>